<?php declare(strict_types=1);$mnBatch=$mnState['batch'];$mnCanBatch=$mnState['queue_available']&&!$mnState['review_changed']&&$mnState['original_review']!==null&&$mnBatch['http_status']===0&&$mnBatch['ready_count']>0; ?>
<section class="dwf-card" id="voucher-mail-all" data-voucher-mail-batch><h3><?= e($vmI('Gutscheine an alle Mitglieder senden')) ?></h3><p><?= e($vmF('{count} persönliche Mails zur Vormerkung',['count'=>$mnBatch['ready_count']])) ?></p><p><?= e($vmF('{count} Mitglieder nicht vorgemerkt',['count'=>$mnBatch['skipped_count']])) ?></p><p><?= e($vmI('Jedes Mitglied erhält nur seine eigenen Gutscheine. Die Bestätigung umfasst alle aktuell berechtigten Empfänger, auch auf weiteren Seiten.')) ?></p>
<?php if($mnState['review_changed']):?><p class="dwf-alert" role="alert"><?= e($vmI('Empfänger, Gutscheine oder Versandstatus geändert. Bitte Sammelversand erneut prüfen.')) ?></p><?php if($mnState['original_review']!==null):?><p><?= e($vmF('Ursprüngliche Prüfung: {ready} bereit, {skipped} übersprungen.',['ready'=>count($mnState['original_review']['ready']),'skipped'=>count($mnState['original_review']['skipped'])])) ?></p><?php endif;endif ?>
<?php foreach(['ready'=>'Bereit zur Vormerkung','skipped'=>'Nicht versendet']as$mnGroup=>$mnLabel):?><section class="dwf-card" data-voucher-mail-batch-<?= e($mnGroup) ?>><h4><?= e($vmI($mnLabel)) ?></h4><?php $mnSearch($mnGroup,$mnGroup==='ready'?'Bereite Empfänger durchsuchen':'Nicht vorgemerkte Mitglieder durchsuchen');if(isset($mnBatch['errors'][$mnGroup])):?><p class="dwf-alert dwf-error" role="alert"><?= e($vmI($mnBatch['errors'][$mnGroup])) ?></p><?php endif;echo $mnPager($mnGroup,$mnBatch[$mnGroup],$mnGroup==='ready'?'Bereite Gutschein-Mailseiten':'Übersprungene Gutschein-Mailseiten'); ?>
<?php foreach($mnBatch[$mnGroup]['rows']??[]as$mnRecipient):?><article class="personal-voucher-event" data-voucher-mail-batch-person><h5><?= e($mnRecipient['name']) ?></h5><?php if($mnGroup==='ready'):?><p><?= e($mnRecipient['email']) ?> · <?= e($vmF('{count} verfügbare Karten',['count'=>$mnRecipient['count']])) ?></p><a class="btn btn-outline theme-secondary dwf-button" href="<?= e($mnUrl(['voucher_mail_section'=>'personal','voucher_mail_person'=>$mnRecipient['id']])) ?>"><?= e($vmI('Persönliche Mail prüfen')) ?></a><?php else:?><p><?= e($vmI($mnRecipient['reason'])) ?></p><?php endif ?></article><?php endforeach ?><?= $mnPager($mnGroup,$mnBatch[$mnGroup],$mnGroup==='ready'?'Bereite Gutschein-Mailseiten':'Übersprungene Gutschein-Mailseiten') ?></section><?php endforeach ?>
<form method="post" data-voucher-mail-batch-send data-confirm-other-drafts <?= $vmState['proposal_restored']?'data-unsaved-changes':'' ?>><?= $mnForm($mnDraft) ?><label class="voucher-manager-person"><input type="checkbox" name="voucher_mail_confirm" value="1" required <?= ($mnDraft['values']['voucher_mail_confirm']??'')==='1'?'checked':'' ?>><span><?= e($vmI('Ich habe alle bereiten Empfänger, die gespeicherte Vorlage und die Gründe für übersprungene Mitglieder geprüft.')) ?></span></label><button class="btn btn-solid theme-primary dwf-button" <?= $mnCanBatch?'':'disabled' ?>><?= e($vmI('Geprüften Sammelversand vormerken')) ?></button><?php $mnReview($mnDraft); ?></form></section>
